"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$root = "E:'"\\codex-LOOP\\codex-loop-s-f2\"
"'$shaFile = Join-Path $root "SHA256SUMS"
$lines = Get-Content $shaFile -Encoding UTF8
$matches_count = 0; $mismatches = @(); $missing = @()
foreach ($line in $lines) {
    $line = $line.Trim()
    if (-not $line) { continue }
    $parts = $line -split '"'  ', 2
    if ("'$parts.Length -ne 2) { continue }
    $expected = $parts[0]
    $rel = $parts[1]
    $winPath = Join-Path $root ($rel -replace '"'/', '\\')
    if (-not (Test-Path "'$winPath -PathType Leaf)) {
        $missing += $rel
        continue
    }
    $actual = (Get-FileHash -Path $winPath -Algorithm SHA256).Hash.ToLower()
    if ($actual -eq $expected) {
        $matches_count++
    } else {
        $mismatches += [PSCustomObject]@{ File=$rel; Expected=$expected; Actual=$actual }
    }
}
Write-Output "Total entries: $($lines.Count)"
Write-Output "Matched: $matches_count"
Write-Output "Missing: $($missing.Count)"
Write-Output "Mismatches: $($mismatches.Count)"
if ($missing.Count -gt 0) { Write-Output "--- MISSING ---"; $missing | ForEach-Object { Write-Output "  $_" } }
if ($mismatches.Count -gt 0) { Write-Output "--- MISMATCHES ---"; $mismatches | ForEach-Object { Write-Output "  $($_.File)"; Write-Output "    expected: $($_.Expected)"; Write-Output "    actual:   $($_.Actual)" } }'

