"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$root = "E:'"\\codex-LOOP\\codex-loop-s-f2\"
"'$managedFile = Join-Path $root "config'"\\managed_files_v2.txt\"
"'$shaFile = Join-Path $root "SHA256SUMS"

$managedLines = (Get-Content $managedFile -Encoding UTF8) | Where-Object { $_.Trim() -ne '"'' -and -not "'$_.StartsWith('"'#') }
"'$shaEntries = @{}
foreach ($line in (Get-Content $shaFile -Encoding UTF8)) {
    $line = $line.Trim()
    if (-not $line) { continue }
    $parts = $line -split '"'  ', 2
    if ("'$parts.Length -eq 2) { $shaEntries[$parts[1]] = $parts[0] }
}

Write-Output "managed_files_v2.txt entries: $($managedLines.Count)"
Write-Output "SHA256SUMS entries: $($shaEntries.Count)"

$inManaged_notSha = $managedLines | Where-Object { -not $shaEntries.ContainsKey($_) }
$inSha_notManaged = $shaEntries.Keys | Where-Object { $managedLines -notcontains $_ }

Write-Output "In managed_files but NOT in SHA256SUMS: $($inManaged_notSha.Count)"
if ($inManaged_notSha.Count -gt 0) { $inManaged_notSha | ForEach-Object { Write-Output "  MANAGED_ONLY: $_" } }

Write-Output "In SHA256SUMS but NOT in managed_files: $($inSha_notManaged.Count)"
if ($inSha_notManaged.Count -gt 0) { $inSha_notManaged | Sort-Object | ForEach-Object { Write-Output "  SHA_ONLY: $_" } }'

